class User:
    def __init__(self, name):
        self.name = name
    @classmethod
    def from_email(cls, email):
        return cls(email.split("@")[0])
u = User.from_email("dana@x.io")
print(u.name)

class Base:
    @classmethod
    def which(cls):
        return cls.__name__
class Child(Base):
    pass
print(Child.which())

class Checker:
    @staticmethod
    def ok(code):
        return 200 <= code < 300
c = Checker()
print(Checker.ok(204), c.ok(500))

class Circle:
    def __init__(self, r):
        self.r = r
    @property
    def area(self):
        return self.r * self.r * 3
c = Circle(2)
print(c.area)

class Order:
    def __init__(self):
        self.items = [10, 20]
    @property
    def total(self):
        return sum(self.items)
o = Order()
print(o.total)
o.items.append(5)
print(o.total)

class Job:
    @property
    def state(self):
        return "queued"
j = Job()
print(j.state())

class Item:
    @property
    def price(self):
        return 100
i = Item()
i.price = 50

class Acc:
    @property
    def email(self):
        return self._email
    @email.setter
    def email(self, v):
        if "@" not in v:
            raise ValueError(v)
        self._email = v
a = Acc()
a.email = "qa@x.io"
print(a.email)

class Cfg:
    @property
    def mode(self):
        return self._mode
    @mode.setter
    def mode(self, v):
        self.mode = v
c = Cfg()
c.mode = "fast"

class Box:
    def kind(cls):
        return cls
b = Box()
print(b.kind() is Box, b.kind() is b)

class Report:
    @classmethod
    def build(cls):
        return cls.__name__ + "!"
r = Report()
print(r.build())

class Temp:
    @staticmethod
    def to_f(c):
        return c * 9 // 5 + 32
Temp.to_f(100)
